/*
  Project Byrmalda v5  -  ESP32-S3 N16R8
  Меню: Настройки / Калькулятор (как Photomath: шаги решения) / Режим ИИ
  Управление: джойстик (X, Y) + кнопка джойстика.
    - джойстик: перемещение, клик: выбрать, удержание кнопки (0.7 c): назад / отмена

  Что нового в v2:
    * кадровый буфер в PSRAM + отправка на экран только изменённой области -> нет мерцания, быстро
    * обои на весь экран (плавное масштабирование), они же затемнённым фоном на всех экранах
    * плавная анимация меню, плавная подсветка, крутилка при ожидании ИИ
    * Wi-Fi держится всегда: отдельная задача следит за связью и переподключает сама,
      режим сна Wi-Fi выключен, мощность передатчика максимальная, процессор всегда 240 МГц

    * три сети (одна за раз, пароль byrmalda123): Byrmalda_Remote (экран+кнопки), Byrmalda (Wi-Fi/API),
      Byrmalda_OTA (загрузка новой прошивки без стирания настроек). Переключение: Настройки -> Сеть ESP32
      или страница http://192.168.4.1/net. При подключении нужная страница открывается сама.

  Arduino IDE:
    Плата: ESP32S3 Dev Module, Flash 16MB, PSRAM: "OPI PSRAM" (ОБЯЗАТЕЛЬНО), USB CDC On Boot: Enabled\n    Для OTA: выберите схему разделов с двумя OTA-разделами (например, 16MB с OTA), затем соберите .bin приложения.
    Библиотеки: Adafruit GFX, Adafruit ST7789 (или Adafruit ILI9341),
                U8g2_for_Adafruit_GFX, ArduinoJson (версия 7.x),
                (QR-код делает встроенный в ядро ESP32 компонент, ставить ничего не нужно)

  Подключение (меняется в блоке ПИНЫ):
    Дисплей 1.54" 240x240 (ST7789V, 8 выводов): SCL=GPIO12, SDA=GPIO11, RES=GPIO8,
                A0(=DC)=GPIO9, CS=GPIO10, BLK=GPIO7, VCC=3.3V, GND
    Джойстик: VRx=GPIO1, VRy=GPIO2, SW=GPIO4 (+3.3V, GND)
    (GPIO 35-37 заняты PSRAM, ADC2-пины не трогаем: они конфликтуют с Wi-Fi)

  Быстрый ввод с телефона: Настройки -> "Ввод с телефона (QR)" -> отсканировать QR,
  подключиться к сети Byrmalda, заполнить форму на открывшейся странице.

  Или через Serial Monitor (115200), по одной строке:
    ssid=МояСеть   pass=пароль   key=sk-...   model=gpt-4o-mini   url=https://...
*/

