// ======================= ДИСПЛЕЙ: БУФЕР КАДРА + ЧАСТИЧНАЯ ПЕРЕРИСОВКА =======================
// Всё рисуется в буфер в PSRAM (tft = буфер). present() сравнивает кадр с тем, что уже на экране,
// и отправляет по SPI только прямоугольник, где что-то изменилось. Мерцания нет, кадры быстрые.
static void* bigAlloc(size_t n) { void* p = ps_malloc(n); if (!p) p = malloc(n); return p; }

class Canvas : public Adafruit_GFX {
 public:
  uint16_t* buf;
  bool dirty = true;
  Canvas(int16_t w, int16_t h) : Adafruit_GFX(w, h) {
    buf = (uint16_t*)bigAlloc((size_t)w * h * 2);
    if (buf) memset(buf, 0, (size_t)w * h * 2);
  }
  void drawPixel(int16_t x, int16_t y, uint16_t c) override {
    if ((unsigned)x >= (unsigned)_width || (unsigned)y >= (unsigned)_height) return;
    buf[(int)y * _width + x] = c; dirty = true;
  }
  void fillRect(int16_t x, int16_t y, int16_t w, int16_t h, uint16_t c) override {
    int x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;
    int x1 = x + w > _width ? _width : x + w, y1 = y + h > _height ? _height : y + h;
    if (x1 <= x0 || y1 <= y0) return;
    for (int yy = y0; yy < y1; yy++) {
      uint16_t* p = buf + yy * _width + x0;
      for (int xx = x0; xx < x1; xx++) *p++ = c;
    }
    dirty = true;
  }
  void drawFastHLine(int16_t x, int16_t y, int16_t w, uint16_t c) override { fillRect(x, y, w, 1, c); }
  void drawFastVLine(int16_t x, int16_t y, int16_t h, uint16_t c) override { fillRect(x, y, 1, h, c); }
  void fillScreen(uint16_t c) override { fillRect(0, 0, _width, _height, c); }
};

Canvas* cvp = nullptr;
#define tft (*cvp)
uint16_t* shadowBuf = nullptr;   // то, что сейчас на экране
uint16_t* bgBuf = nullptr;       // фон (обои)
SemaphoreHandle_t presMtx = nullptr;
volatile uint32_t frameVer = 1;  // номер кадра (для веб-страницы)

static void presentLocked(bool force) {
  if (!cvp || !cvp->buf) return;
  if (!cvp->dirty && !force) return;
  cvp->dirty = false;

  uint16_t* frame = cvp->buf;
  frameVer++;

  // Один непрерывный прямоугольник обновления вместо десятков/сотен
  // отдельных окон на каждой строке. Это уменьшает SPI overhead и
  // предотвращает видимые горизонтальные полосы при движении подсветки.
  int minX = 0, minY = 0, maxX = W - 1, maxY = H - 1;

  if (!force && shadowBuf) {
    minX = W; minY = H; maxX = -1; maxY = -1;

    for (int y = 0; y < H; ++y) {
      const uint16_t* cur = frame + (size_t)y * W;
      const uint16_t* old = shadowBuf + (size_t)y * W;
      for (int x = 0; x < W; ++x) {
        if (cur[x] != old[x]) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    }

    // Кадр не содержит видимых изменений.
    if (maxX < minX || maxY < minY) return;
  }

  const int rectW = maxX - minX + 1;
  const int rectH = maxY - minY + 1;

  lcd.startWrite();
  lcd.setAddrWindow(minX, minY, rectW, rectH);

  // Контроллер дисплея принимает пиксели построчно внутри одного окна.
  for (int y = minY; y <= maxY; ++y) {
    const uint16_t* row = frame + (size_t)y * W + minX;
    lcd.writePixels((uint16_t*)row, rectW);
    if (shadowBuf) {
      uint16_t* old = shadowBuf + (size_t)y * W + minX;
      memcpy(old, row, (size_t)rectW * sizeof(uint16_t));
    }
  }

  lcd.endWrite();

  // При первом полном кадре или принудительном обновлении синхронизируем
  // shadow buffer целиком.
  if (shadowBuf && force) {
    memcpy(shadowBuf, frame, (size_t)W * H * sizeof(uint16_t));
  }
}
static void present(bool force) {
  if (presMtx) xSemaphoreTake(presMtx, portMAX_DELAY);
  presentLocked(force);
  if (presMtx) xSemaphoreGive(presMtx);
}
static inline void present() { present(false); }

void bgFill() {
  if (bgBuf) memcpy(cvp->buf, bgBuf, (size_t)W * H * 2); else cvp->fillScreen(C_BG);
  cvp->dirty = true;
}
void bgRect(int x, int y, int w, int h) {
  if (!bgBuf) { cvp->fillRect(x, y, w, h, C_BG); return; }
  int x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > W ? W : x + w, y1 = y + h > H ? H : y + h;
  if (x1 <= x0 || y1 <= y0) return;
  for (int yy = y0; yy < y1; yy++) memcpy(cvp->buf + yy * W + x0, bgBuf + yy * W + x0, (x1 - x0) * 2);
  cvp->dirty = true;
}
static inline uint16_t blend565(uint16_t fg, uint16_t bg, uint8_t a) {   // a: 0..32
  uint32_t f = (fg | ((uint32_t)fg << 16)) & 0x07E0F81FUL, b = (bg | ((uint32_t)bg << 16)) & 0x07E0F81FUL;
  uint32_t r = ((((f - b) * a) >> 5) + b) & 0x07E0F81FUL;
  return (uint16_t)(r | (r >> 16));
}
// полупрозрачный скруглённый прямоугольник (a: 0..32, r: радиус углов)
void blendRect(int x, int y, int w, int h, uint16_t col, uint8_t a, int r) {
  uint32_t fg = (col | ((uint32_t)col << 16)) & 0x07E0F81FUL;
  uint16_t* b = cvp->buf;
  for (int j = 0; j < h; j++) {
    int yy = y + j;
    if (yy < 0 || yy >= H) continue;
    int ins = 0;
    if (r > 0) {
      int jj = j < r ? j : (j >= h - r ? h - 1 - j : -1);
      if (jj >= 0) { float dy = r - jj - 0.5f; ins = r - (int)(sqrtf((float)(r * r) - dy * dy) + 0.5f); }
    }
    int xa = x + ins, xb = x + w - ins;
    if (xa < 0) xa = 0;
    if (xb > W) xb = W;
    uint16_t* p = b + yy * W;
    for (int i = xa; i < xb; i++) {
      uint32_t bg = (p[i] | ((uint32_t)p[i] << 16)) & 0x07E0F81FUL;
      uint32_t res = ((((fg - bg) * a) >> 5) + bg) & 0x07E0F81FUL;
      p[i] = (uint16_t)(res | (res >> 16));
    }
  }
  cvp->dirty = true;
}

