static bool webGuard() {   // сайт только из сетей самой ESP32 (из домашней сети нельзя - иначе любой в LAN сможет прошить)
#if WEB_LAN_ACCESS
  return true;
#else
  if (web.client().localIP() == WiFi.softAPIP()) return true;
  web.send(403, "text/plain", "Only via ESP32 network");
  return false;
#endif
}
static void webRoot() {
  web.sendHeader("Location", AP_PATHS[apMode], true);
  web.send(302, "text/plain", "");
}
static void remoteRoot() {
  if (!webGuard()) return;
  String p = FPSTR(REMOTE_PAGE);
  p.replace("%W%", String(W)); p.replace("%H%", String(H));
  web.send(200, "text/html; charset=utf-8", p);
}
static void remoteFrame() {
  if (!webGuard()) return;
  uint32_t v = web.arg("v").toInt();
  if (!cvp || !cvp->buf || v == frameVer) { web.send(204, "text/plain", ""); return; }
  size_t n = (size_t)W * H * 2;
  web.sendHeader("X-V", String(frameVer));
  web.sendHeader("Cache-Control", "no-store");
  web.setContentLength(n);
  web.send(200, "application/octet-stream", "");
  web.sendContent((const char*)cvp->buf, n);
}
static void remoteKey() {
  if (!webGuard()) return;
  String k = web.arg("k");
  Key v = K_NONE;
  if (k == "u") v = K_UP; else if (k == "d") v = K_DOWN; else if (k == "l") v = K_LEFT;
  else if (k == "r") v = K_RIGHT; else if (k == "o") v = K_CLICK; else if (k == "b") v = K_LONG;
  if (v != K_NONE) injectKey = v;
  web.send(200, "text/plain", "ok");
}
static void setupPage() { if (webGuard()) web.send(200, "text/html; charset=utf-8", portalPage()); }
static void setupSave() { if (webGuard()) portalSave(); }

