// ======================= ЗАГРУЗКА И МЕНЮ =======================
// обои на весь экран: плавное (билинейное) масштабирование 120x120 -> размер экрана
static void buildWall() {
  if (!bgBuf) return;
  for (int y = 0; y < H; y++) {
    uint32_t fy = (uint32_t)y * (119u << 8) / (H - 1);
    int sy = fy >> 8, ty = fy & 255, sy1 = sy < 119 ? sy + 1 : 119;
    for (int x = 0; x < W; x++) {
      uint32_t fx = (uint32_t)x * (119u << 8) / (W - 1);
      int sx = fx >> 8, tx = fx & 255, sx1 = sx < 119 ? sx + 1 : 119;
      uint16_t p00 = WALL[sy * 120 + sx], p10 = WALL[sy * 120 + sx1];
      uint16_t p01 = WALL[sy1 * 120 + sx], p11 = WALL[sy1 * 120 + sx1];
      int w00 = (256 - tx) * (256 - ty), w10 = tx * (256 - ty), w01 = (256 - tx) * ty, w11 = tx * ty;
      int r = (((p00 >> 11) & 31) * w00 + ((p10 >> 11) & 31) * w10 + ((p01 >> 11) & 31) * w01 + ((p11 >> 11) & 31) * w11) >> 16;
      int g = (((p00 >> 5) & 63) * w00 + ((p10 >> 5) & 63) * w10 + ((p01 >> 5) & 63) * w01 + ((p11 >> 5) & 63) * w11) >> 16;
      int b = ((p00 & 31) * w00 + (p10 & 31) * w10 + (p01 & 31) * w01 + (p11 & 31) * w11) >> 16;
      bgBuf[y * W + x] = (uint16_t)((r << 11) | (g << 5) | b);
    }
  }
}
// после загрузки обои затемняются и подкрашиваются в синий: это фон всего интерфейса
static void darkenWall() {
  if (!bgBuf) return;
  for (int i = 0; i < W * H; i++) {
    uint16_t c = bgBuf[i];
    int r = ((c >> 11) & 31) * 50 >> 8, g = ((c >> 5) & 63) * 60 >> 8, b = (((c & 31) * 90) >> 8) + 2;
    if (b > 31) b = 31;
    bgBuf[i] = (uint16_t)((r << 11) | (g << 5) | b);
  }
}

static void bootCompose(float prog, const String& wtxt, uint16_t wcol) {
  memcpy(cvp->buf, bgBuf, (size_t)W * H * 2);
  int sy = H - 150;
  for (int y = sy; y < H; y++) blendRect(0, y, W, 1, 0x0000, (uint8_t)((y - sy) * 30 / 150), 0);   // плавное затемнение снизу
  txtC("Project Byrmalda", W / 2 + 1, H - 77, 0x0000, F_BIG);
  txtC("Project Byrmalda", W / 2, H - 78, C_TXT, F_BIG);
  txtC("ESP32-S3  -  v2", W / 2, H - 62, C_ACC, F_SMALL);
  int bx = 30, bw = W - 60, by = H - 46;
  blendRect(bx, by, bw, 6, 0x0000, 22, 3);
  int fw = (int)(bw * prog);
  if (fw >= 6) blendRect(bx, by, fw, 6, C_ACC, 32, 3);
  txtC(wtxt, W / 2, H - 22, wcol, F_SMALL);
}
static void bootWifiTxt(String& t, uint16_t& c) {
  if (WiFi.status() == WL_CONNECTED) { t = "Wi-Fi: подключено"; c = C_OK; }
  else if (cfg.ssid.length()) { t = "Wi-Fi: подключаюсь..."; c = C_TXT; }
  else { t = "Wi-Fi: не настроен"; c = C_DIM; }
}
void bootScreen() {
  buildWall();
  String wt = "Запуск..."; uint16_t wc = C_DIM;
  bootCompose(0, wt, wc);
  present(true);                                   // первый кадр при погашенной подсветке
  for (int b = 0; b <= BL_NORMAL; b += 5) { analogWrite(PIN_BL, b); delay(4); }   // плавное появление
  analogWrite(PIN_BL, BL_NORMAL); blCur = blTgt = BL_NORMAL;
  const uint32_t DUR = 1600;
  uint32_t t0 = millis();
  while (true) {
    uint32_t e = millis() - t0;
    if (e >= DUR) break;
    float p = (float)e / DUR; p = 1.0f - (1.0f - p) * (1.0f - p) * (1.0f - p);
    bootWifiTxt(wt, wc);
    bootCompose(p, wt, wc);
    present();
    delay(1);
  }
  bootWifiTxt(wt, wc);
  bootCompose(1.0f, wt, wc);
  present();
  delay(300);
  darkenWall();
}

// ---- меню
static const int MC_Y0 = 40, MC_H = 54, MC_G = 6;
static int cardY(int i) { return MC_Y0 + i * (MC_H + MC_G); }
int wifiSig() {   // -1 не настроен, 0 нет связи, 1..4 уровень
  if (!cfg.ssid.length()) return -1;
  if (WiFi.status() != WL_CONNECTED) return 0;
  int r = WiFi.RSSI();
  return r > -55 ? 4 : (r > -65 ? 3 : (r > -75 ? 2 : 1));
}
static void drawWifiIcon(int x, int y) {   // x,y - левый нижний угол
  int s = wifiSig();
  uint16_t off = RGB(70, 76, 96);
  for (int i = 0; i < 4; i++) {
    int bh = 5 + i * 4;
    uint16_t c = off;
    if (s > i) c = (s >= 2) ? C_OK : RGB(255, 190, 60);
    else if (s == 0 && i == 0) c = C_ERR;
    tft.fillRect(x + i * 6, y - bh, 4, bh, c);
  }
}
static void icoGear(int cx, int cy, uint16_t c) {
  for (int k = 0; k < 8; k++) {
    float a = k * (float)M_PI / 4;
    tft.fillCircle(cx + lroundf(cosf(a) * 11), cy + lroundf(sinf(a) * 11), 2, c);
  }
  tft.drawCircle(cx, cy, 8, c); tft.drawCircle(cx, cy, 7, c); tft.drawCircle(cx, cy, 3, c);
}
static void icoCalc(int cx, int cy, uint16_t c) {
  tft.drawRoundRect(cx - 10, cy - 13, 20, 26, 3, c);
  tft.fillRect(cx - 7, cy - 10, 14, 6, c);
  for (int j = 0; j < 2; j++) for (int i = 0; i < 3; i++) tft.fillRect(cx - 7 + i * 5, cy + 1 + j * 6, 4, 4, c);
}
static void icoAI(int cx, int cy, uint16_t c) {
  tft.fillTriangle(cx, cy - 13, cx + 4, cy, cx - 4, cy, c);
  tft.fillTriangle(cx, cy + 13, cx + 4, cy, cx - 4, cy, c);
  tft.fillTriangle(cx - 13, cy, cx, cy - 4, cx, cy + 4, c);
  tft.fillTriangle(cx + 13, cy, cx, cy - 4, cx, cy + 4, c);
  tft.fillCircle(cx + 11, cy - 11, 2, c);
}
static void menuCompose(float hy) {
  static const char* T[3] = {"Настройки", "Калькулятор", "Режим ИИ"};
  static const char* S[3] = {"Wi-Fi, ключ ИИ, модель", "Решение по шагам", "Чат с нейросетью"};
  bgFill();
  txt("Byrmalda", 13, 28, 0x0000, F_BIG);
  txt("Byrmalda", 12, 27, C_TXT, F_BIG);
  drawWifiIcon(W - 12 - 22, 26);
  for (int i = 0; i < 3; i++) blendRect(10, cardY(i), W - 20, MC_H, RGB(8, 10, 18), 19, 10);
  int iy = (int)(hy + 0.5f);
  blendRect(10, iy, W - 20, MC_H, C_SEL, 27, 10);                // «бегущая» подсветка
  blendRect(10, iy + 10, 4, MC_H - 20, C_ACC, 32, 2);            // акцентная полоска
  for (int i = 0; i < 3; i++) {
    int y = cardY(i);
    bool near = fabsf(hy - y) < MC_H / 2;
    uint16_t ic = near ? C_ACC : C_DIM;
    int cx = 38, cy = y + MC_H / 2;
    if (i == 0) icoGear(cx, cy, ic); else if (i == 1) icoCalc(cx, cy, ic); else icoAI(cx, cy, ic);
    txt(T[i], 66, y + 25, C_TXT, F_BIG);
    txt(S[i], 66, y + 43, near ? C_TXT : C_DIM, F_SMALL);
  }
  txtC("джойстик - выбор     клик - открыть", W / 2, H - 6, C_DIM, F_SMALL);
}
int menuScreen() {
  static int sel = 0;
  float hy = cardY(sel);
  int lastSig = wifiSig();
  uint32_t lastChk = millis();
  menuCompose(hy);
  present();
  while (true) {
    Key k = readKey();
    bool redraw = false;
    if (k == K_UP) sel = (sel + 2) % 3;
    else if (k == K_DOWN) sel = (sel + 1) % 3;
    else if (k == K_CLICK) return sel;
    float tgt = cardY(sel);
    if (fabsf(tgt - hy) > 0.4f) {
      hy += (tgt - hy) * 0.40f;
      if (fabsf(tgt - hy) <= 0.4f) hy = tgt;
      redraw = true;
    }
    uint32_t now = millis();
    if (now - lastChk > 1000) {
      lastChk = now;
      int s = wifiSig();
      if (s != lastSig) { lastSig = s; redraw = true; }
    }
    if (redraw) { menuCompose(hy); present(); delay(1); }
    else if (k == K_NONE) idleWait();
  }
}

// ======================= SETUP / LOOP =======================
void setup() {
  setCpuFrequencyMhz(CPU_MHZ);
  Serial.begin(115200);
  analogWriteFrequency(PIN_BL, 20000);
  analogWrite(PIN_BL, 0);                 // подсветка погашена, пока рисуем первый кадр
  pinMode(PIN_JSW, INPUT_PULLUP);
  analogReadResolution(12);

  SPI.begin(PIN_SCK, -1, PIN_MOSI, PIN_CS);
#if USE_ST7789
  lcd.init(TFT_W, TFT_H, TFT_SPI_MODE);
  lcd.setSPISpeed(TFT_SPI_HZ);
#else
  lcd.begin(TFT_SPI_HZ);
#endif
  lcd.setRotation(ROTATION);
  W = lcd.width(); H = lcd.height();
  lcd.fillScreen(0);

  presMtx = xSemaphoreCreateMutex();
  cvp = new Canvas(W, H);
  shadowBuf = (uint16_t*)bigAlloc((size_t)W * H * 2);
  bgBuf = (uint16_t*)bigAlloc((size_t)W * H * 2);
  if (!cvp || !cvp->buf || !bgBuf) {
    analogWrite(PIN_BL, BL_NORMAL);
    while (true) { Serial.println("Нет памяти под экран: включите PSRAM = OPI PSRAM в меню Tools"); delay(2000); }
  }
  if (shadowBuf) memset(shadowBuf, 0, (size_t)W * H * 2);
  u8.begin(*cvp);

  long sx = 0, sy = 0;
  for (int i = 0; i < 32; i++) { sx += analogRead(PIN_JX); sy += analogRead(PIN_JY); delay(2); }
  joyCX = sx / 32; joyCY = sy / 32;

  loadCfg();
  wifiStart();            // Wi-Fi стартует сразу и дальше следит за собой
  remoteStart();          // сайт-пульт
  bootScreen();
  lastAct = millis();
}

void loop() {
  switch (menuScreen()) {
    case 0: settingsScreen(); break;
    case 1: calcScreen(); break;
    case 2: aiScreen(); break;
  }
}
